from pathlib import Path
program='''from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    # Find zero regions reachable from the edge (4-connectivity).
    exterior = [[False]*w for _ in range(h)]
    q = deque()
    for r in range(h):
        for c in (0, w-1):
            if grid[r][c] == 0 and not exterior[r][c]:
                exterior[r][c] = True; q.append((r,c))
    for c in range(w):
        for r in (0, h-1):
            if grid[r][c] == 0 and not exterior[r][c]:
                exterior[r][c] = True; q.append((r,c))
    dirs4 = ((1,0),(-1,0),(0,1),(0,-1))
    while q:
        r,c=q.popleft()
        for dr,dc in dirs4:
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and not exterior[nr][nc]:
                exterior[nr][nc]=True; q.append((nr,nc))
    # Enclosed zero pixels bordering the 1-wall become color 3.
    boundary3=set()
    for r in range(h):
        for c in range(w):
            if grid[r][c]==0 and not exterior[r][c]:
                if any(0<=r+dr<h and 0<=c+dc<w and grid[r+dr][c+dc]==1 for dr,dc in dirs4):
                    boundary3.add((r,c))
    for r,c in boundary3: out[r][c]=3
    if not boundary3:
        return out
    # Locate 8-connected 1 components that border enclosed zero regions.
    seen=set(); marked=set()
    dirs8=tuple((dr,dc) for dr in (-1,0,1) for dc in (-1,0,1) if (dr,dc)!=(0,0))
    for r in range(h):
        for c in range(w):
            if grid[r][c]!=1 or (r,c) in seen: continue
            comp=[]; q=deque([(r,c)]); seen.add((r,c))
            while q:
                x,y=q.popleft(); comp.append((x,y))
                for dr,dc in dirs8:
                    nx,ny=x+dr,y+dc
                    if 0<=nx<h and 0<=ny<w and grid[nx][ny]==1 and (nx,ny) not in seen:
                        seen.add((nx,ny)); q.append((nx,ny))
            if any((x+dr,y+dc) in boundary3 for x,y in comp for dr,dc in dirs4 if 0<=x+dr<h and 0<=y+dc<w):
                marked.update(comp)
    # Add a one-cell outside halo, including diagonal neighbors.
    for r,c in marked:
        for dr,dc in dirs8:
            nr,nc=r+dr,c+dc
            if 0<=nr<h and 0<=nc<w and grid[nr][nc]==0 and out[nr][nc]==0:
                out[nr][nc]=2
    return out
'''
